body.script:
(function() {
    "use strict";
    const root = document.getElementById("kd-root");
    const displayId = root ? root.dataset.displayId : "1";
    let stages = [];
    let orders = [];
    let categories = [];
    let currentTab = "to_cook";
    let currentTimeFilter = "now";
    let currentPresetFilter = "all";
    let currentCategoryFilter = "all";
    let zoomScale = 1;
    let doneLines = JSON.parse(localStorage.getItem("hkd_done_lines") || "{}");
    let soundEnabled = localStorage.getItem("hkd_sound_enabled") !== "0";
    let audioCtx = null;
    let previousOrderStages = {};
    let initialLoad = true;
    let lastMovedAction = null;

    function getAudioContext() {
        if (!audioCtx) {
            const AudioContext = window.AudioContext || window.webkitAudioContext;
            if (AudioContext) {
                audioCtx = new AudioContext();
            }
        }
        if (audioCtx && audioCtx.state === "suspended") {
            audioCtx.resume();
        }
        return audioCtx;
    }

    function playTone(freq, duration, type, delay, gainLevel) {
        if (!soundEnabled) return;
        try {
            const ctx = getAudioContext();
            if (!ctx) return;
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            const now = ctx.currentTime + (delay || 0);
            osc.type = type || "sine";
            osc.frequency.setValueAtTime(freq, now);
            gain.gain.setValueAtTime(gainLevel || 0.15, now);
            gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(now);
            osc.stop(now + duration);
        } catch (e) {}
    }

    // 1. New Order (To cook): Ding-Dong Chime (Warm, resonant two-tone chime)
    function playDingDongChime() {
        if (!soundEnabled) return;
        try {
            const ctx = getAudioContext();
            if (!ctx) return;
            const now = ctx.currentTime;

            // Tone 1 ("Ding" at t=0): High resonant tubular chime
            const dingPartials = [
                { freq: 659.25, gain: 0.28, decay: 0.9 },   // E5 fundamental
                { freq: 1318.5, gain: 0.12, decay: 0.5 },   // E6 harmonic
                { freq: 1977.7, gain: 0.06, decay: 0.25 }   // B6 shimmer
            ];
            dingPartials.forEach(p => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "sine";
                osc.frequency.setValueAtTime(p.freq, now);
                gain.gain.setValueAtTime(p.gain, now);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + p.decay);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(now);
                osc.stop(now + p.decay);
            });

            // Tone 2 ("Dong" at t=0.32s): Deep, warm lower bell resonance
            const dongPartials = [
                { freq: 523.25, gain: 0.32, decay: 1.3 },   // C5 fundamental
                { freq: 1046.5, gain: 0.14, decay: 0.8 },   // C6 harmonic
                { freq: 1569.7, gain: 0.05, decay: 0.35 }   // G6 shimmer
            ];
            dongPartials.forEach(p => {
                const t = now + 0.32;
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "sine";
                osc.frequency.setValueAtTime(p.freq, t);
                gain.gain.setValueAtTime(p.gain, t);
                gain.gain.exponentialRampToValueAtTime(0.0001, t + p.decay);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(t);
                osc.stop(t + p.decay);
            });
        } catch (e) {}
    }

    // 2. Order Ready: Bright Double-Bell (Crisp double strike waiter/service bell: Ting-Ting!)
    function playBrightDoubleBell() {
        if (!soundEnabled) return;
        try {
            const ctx = getAudioContext();
            if (!ctx) return;
            const now = ctx.currentTime;

            // Strike 1 (t = 0): Crisp metallic bell tap
            const strike1 = [1567.98, 2351.97, 3135.96];
            strike1.forEach((f, idx) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "triangle";
                osc.frequency.setValueAtTime(f, now);
                const g = (idx === 0 ? 0.30 : 0.12 / idx);
                gain.gain.setValueAtTime(g, now);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.22);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(now);
                osc.stop(now + 0.22);
            });

            // Strike 2 (t = 0.14s): Higher, bright ringing bell tap
            const strike2 = [1760.00, 2640.00, 3520.00, 5280.00];
            strike2.forEach((f, idx) => {
                const t = now + 0.14;
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "sine";
                osc.frequency.setValueAtTime(f, t);
                const g = (idx === 0 ? 0.34 : 0.15 / idx);
                gain.gain.setValueAtTime(g, t);
                gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.70);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(t);
                osc.stop(t + 0.70);
            });
        } catch (e) {}
    }

    // 3. Completed / Done: Ascending Celebration Chime (4-Note Fanfare Chime: C5 -> E5 -> G5 -> C6)
    function playAscendingCelebrationChime() {
        if (!soundEnabled) return;
        try {
            const ctx = getAudioContext();
            if (!ctx) return;
            const now = ctx.currentTime;

            const notes = [
                { freq: 523.25, time: 0.00, decay: 0.38, gain: 0.24 }, // C5 (Do)
                { freq: 659.25, time: 0.12, decay: 0.38, gain: 0.26 }, // E5 (Mi)
                { freq: 783.99, time: 0.24, decay: 0.45, gain: 0.28 }, // G5 (Sol)
                { freq: 1046.50, time: 0.38, decay: 1.20, gain: 0.35 } // High C6 (High Do - triumphant sustained shimmer!)
            ];

            notes.forEach((n, idx) => {
                const t = now + n.time;
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "sine";
                osc.frequency.setValueAtTime(n.freq, t);
                gain.gain.setValueAtTime(n.gain, t);
                gain.gain.exponentialRampToValueAtTime(0.0001, t + n.decay);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(t);
                osc.stop(t + n.decay);

                // Warm harmonic overtone for celebratory richness
                const oscHarm = ctx.createOscillator();
                const gainHarm = ctx.createGain();
                oscHarm.type = "sine";
                oscHarm.frequency.setValueAtTime(n.freq * 2, t);
                gainHarm.gain.setValueAtTime(n.gain * 0.35, t);
                gainHarm.gain.exponentialRampToValueAtTime(0.0001, t + (idx === 3 ? 0.95 : 0.28));
                oscHarm.connect(gainHarm);
                gainHarm.connect(ctx.destination);
                oscHarm.start(t);
                oscHarm.stop(t + (idx === 3 ? 0.95 : 0.28));
            });
        } catch (e) {}
    }

    function playSound(type) {
        if (!soundEnabled) return;
        try {
            getAudioContext();
            switch(type) {
                case "new_order":
                    // 1. Ding-Dong Chime (New order in To cook)
                    playDingDongChime();
                    break;
                case "ready":
                    // 2. Bright Double-Bell (Ready stage)
                    playBrightDoubleBell();
                    break;
                case "completed":
                case "done":
                    // 3. Ascending Celebration Chime (Completed / Done)
                    playAscendingCelebrationChime();
                    break;
                case "reset":
                    // Gentle descending two-tone for Undo / Reset (C5 -> G4)
                    playTone(523.25, 0.16, "sine", 0, 0.18);
                    playTone(392.00, 0.30, "sine", 0.12, 0.18);
                    break;
                case "line_done":
                    // Subtle clean tick for checking an item
                    playTone(880.00, 0.08, "sine", 0, 0.12);
                    break;
                case "late":
                    // Warning alert double-beep
                    playTone(880.00, 0.14, "sawtooth", 0, 0.16);
                    playTone(880.00, 0.14, "sawtooth", 0.18, 0.16);
                    break;
            }
        } catch (e) {}
    }

    // Expose to window for quick testing in browser console
    window.testKitchenSound = playSound;

    function isLineDone(lineId, backendDone) {
        if (backendDone) return true;
        return !!doneLines[lineId];
    }

    async function rpc(route, params) {
        const res = await fetch(route, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                jsonrpc: "2.0",
                method: "call",
                params: params || {},
                id: Date.now()
            })
        });
        const data = await res.json();
        if (data.error) {
            console.error("RPC Error:", data.error);
            throw new Error(data.error.data ? data.error.data.message : "RPC Error");
        }
        return data.result;
    }

    function renderTabs() {
        const container = document.getElementById("kd-tabs-container");
        if (!container) return;

        const toCookStage = stages.find(s => s.name.toLowerCase().includes("cook")) || stages[0];
        const readyStage = stages.find(s => s.name.toLowerCase().includes("ready")) || (stages.length > 1 ? stages[1] : null);
        const completedStage = stages.find(s => s.name.toLowerCase().includes("complete")) || (stages.length > 2 ? stages[2] : null);

        const countToCook = orders.filter(o => toCookStage && o.stage_id === toCookStage.id).length;
        const countReady = orders.filter(o => readyStage && o.stage_id === readyStage.id).length;
        const countCompleted = orders.filter(o => completedStage && o.stage_id === completedStage.id).length;

        let html = `
            <button class="kd-tab ${currentTab === 'all' ? 'active' : ''}" data-tab="all">
                All
            </button>
        `;

        if (toCookStage) {
            html += `
                <button class="kd-tab ${currentTab === 'to_cook' ? 'active' : ''}" data-tab="to_cook">
                    ${toCookStage.name}
                    <span class="kd-tab-badge kd-badge-default">${countToCook}</span>
                </button>
            `;
        }
        if (readyStage) {
            html += `
                <button class="kd-tab ${currentTab === 'ready' ? 'active' : ''}" data-tab="ready">
                    ${readyStage.name}
                    <span class="kd-tab-badge kd-badge-blue">${countReady}</span>
                </button>
            `;
        }
        if (completedStage) {
            html += `
                <button class="kd-tab ${currentTab === 'completed' ? 'active' : ''}" data-tab="completed">
                    ${completedStage.name}
                    <span class="kd-tab-badge kd-badge-green">${countCompleted}</span>
                </button>
            `;
        }

        container.innerHTML = html;

        // Update sidebar counts
        const countTotal = orders.length;
        const countDineIn = orders.filter(o => o.fulfillment_type !== "takeout").length;
        const countTakeout = orders.filter(o => o.fulfillment_type === "takeout").length;

        const elTimeTotal = document.getElementById("count-time-total");
        const elTimeNow = document.getElementById("count-time-now");
        const elTimeToday = document.getElementById("count-time-today");
        const elPresetTotal = document.getElementById("count-preset-total");
        const elPresetDineIn = document.getElementById("count-preset-dinein");
        const elPresetTakeout = document.getElementById("count-preset-takeout");

        if (elTimeTotal) elTimeTotal.textContent = countTotal;
        if (elTimeNow) elTimeNow.textContent = countTotal;
        if (elTimeToday) elTimeToday.textContent = countTotal;
        if (elPresetTotal) elPresetTotal.textContent = countTotal;
        if (elPresetDineIn) elPresetDineIn.textContent = countDineIn;
        if (elPresetTakeout) elPresetTakeout.textContent = countTakeout;

        container.querySelectorAll(".kd-tab").forEach(tab => {
            tab.onclick = () => {
                currentTab = tab.dataset.tab;
                renderTabs();
                renderCards();
            };
        });
    }

    function renderCategories() {
        const container = document.getElementById("kd-side-categories");
        if (!container) return;

        if (!categories.length) {
            container.innerHTML = `<div style="font-size:14px; color:#888; padding:6px 14px;">All Products</div>`;
            return;
        }

        const totalOrders = orders.length;
        let html = `
            <div class="kd-side-row ${currentCategoryFilter === 'all' ? 'active' : ''}" data-category="all">
                <span>All</span>
                <span>${totalOrders}</span>
            </div>
        `;

        categories.forEach(c => {
            const cName = typeof c.name === "object" ? (c.name.en_US || Object.values(c.name)[0] || "Category") : c.name;
            const matchingOrders = orders.filter(o => o.category_ids && o.category_ids.includes(c.id)).length;
            html += `
                <div class="kd-side-row ${String(currentCategoryFilter) === String(c.id) ? 'active' : ''}" data-category="${c.id}">
                    <span>${cName}</span>
                    <span>${matchingOrders}</span>
                </div>
            `;
        });

        container.innerHTML = html;

        const elCategoryTotal = document.getElementById("count-category-total");
        if (elCategoryTotal) elCategoryTotal.textContent = totalOrders;

        container.querySelectorAll(".kd-side-row[data-category]").forEach(row => {
            row.onclick = () => {
                currentCategoryFilter = row.dataset.category;
                renderCategories();
                renderCards();
            };
        });
    }

    function renderCards() {
        const canvas = document.getElementById("kd-canvas");
        if (!canvas) return;

        const toCookStage = stages.find(s => s.name.toLowerCase().includes("cook")) || stages[0];
        const readyStage = stages.find(s => s.name.toLowerCase().includes("ready")) || (stages.length > 1 ? stages[1] : null);
        const completedStage = stages.find(s => s.name.toLowerCase().includes("complete")) || (stages.length > 2 ? stages[2] : null);

        let filtered = orders;
        if (currentTab === "to_cook" && toCookStage) {
            filtered = filtered.filter(o => o.stage_id === toCookStage.id);
        } else if (currentTab === "ready" && readyStage) {
            filtered = filtered.filter(o => o.stage_id === readyStage.id);
        } else if (currentTab === "completed" && completedStage) {
            filtered = filtered.filter(o => o.stage_id === completedStage.id);
        } else if (currentTab === "all") {
            filtered = orders.slice();
        }

        if (currentTab !== "all") {
            if (currentPresetFilter === "dine_in") {
                filtered = filtered.filter(o => o.fulfillment_type !== "takeout");
            } else if (currentPresetFilter === "takeout") {
                filtered = filtered.filter(o => o.fulfillment_type === "takeout");
            }

            if (currentTimeFilter === "now") {
                filtered = filtered.filter(o => (o.minutes_ago || 0) <= 720);
            } else if (currentTimeFilter === "today") {
                filtered = filtered.filter(o => (o.minutes_ago || 0) <= 1440);
            }
        }

        if (currentCategoryFilter !== "all") {
            filtered = filtered.filter(o => o.category_ids && o.category_ids.includes(Number(currentCategoryFilter)));
        }

        if (!filtered.length) {
            canvas.innerHTML = `<div class="kd-empty-state">No orders right now. Orders sent from Point of Sale will appear here automatically.</div>`;
            return;
        }

        canvas.innerHTML = filtered.map((o, idx) => {
            const tableDisp = o.table_number || (o.pos_reference ? o.pos_reference.split(" ").slice(-1)[0] : "");
            const guests = o.customer_count || 1;
            const timer = (o.minutes_ago !== undefined && !isNaN(o.minutes_ago)) ? Math.max(0, Math.abs(o.minutes_ago)) : 0;
            const fulfillment = (o.fulfillment_type === "takeout" ? "Takeout" : "Dine In");

            const linesHtml = (o.lines || []).map(l => {
                const isDone = isLineDone(l.id, l.is_done);
                return `
                    <li class="kd-line-item ${isDone ? 'is-done' : ''}" data-line-id="${l.id}">
                        <div class="kd-line-content">
                            <div class="kd-line-text">
                                <span class="kd-line-qty">${l.qty}x</span>
                                <span class="kd-line-name">${l.name}</span>
                                ${isDone ? '<span style="color:#10b981; font-weight:bold; font-size:14px; margin-left:4px;">✓</span>' : ''}
                            </div>
                            ${l.note ? `<span class="kd-line-note">${l.note}</span>` : ''}
                        </div>
                    </li>
                `;
            }).join("");

            const isTeal = (idx % 2 === 1);
            const headerBg = isTeal ? "background: #80cbc4;" : "background: #ffffff;";

            const stageObj = stages.find(s => s.id === o.stage_id);
            const stageTag = (currentTab === "all" && stageObj) ? `<span style="background:rgba(0,0,0,0.08); font-size:11px; font-weight:700; padding:2px 8px; border-radius:10px;">${stageObj.name}</span>` : "";

            const stageIdx = stages.findIndex(s => s.id === o.stage_id);
            const isLastStage = (stageIdx === stages.length - 1) || (stageObj && stageObj.name.toLowerCase().includes("complete"));
            const nextStage = (stageIdx !== -1 && stageIdx + 1 < stages.length) ? stages[stageIdx + 1] : null;

            let footerHtml = "";
            if (isLastStage) {
                footerHtml = `
                    <div class="kd-card-footer">
                        <button class="kd-card-footer-btn btn-reset" data-order-id="${o.id}">
                            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="margin-right:5px;"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>Reset
                        </button>
                        <button class="kd-card-footer-btn btn-done" data-order-id="${o.id}">
                            Done
                        </button>
                    </div>
                `;
            }

            return `
                <div class="kd-order-card" data-order-id="${o.id}">
                    <div class="kd-card-header-bar" style="${headerBg}" title="Click header to advance entire order">
                        <span class="kd-table-title">${tableDisp}</span>
                        <div style="display:flex; align-items:center; gap:8px;">
                            ${stageTag}
                            <span class="kd-guest-count">
                                <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M16 11c1.66 0 2.99-1.34 2.99-3S17.66 5 16 5c-1.66 0-3 1.34-3 3s1.34 3 3 3zm-8 0c1.66 0 2.99-1.34 2.99-3S9.66 5 8 5C6.34 5 5 6.34 5 8s1.34 3 3 3zm0 2c-2.33 0-7 1.17-7 3.5V19h14v-2.5c0-2.33-4.67-3.5-7-3.5zm8 0c-.29 0-.62.02-.97.05 1.16.84 1.97 1.97 1.97 3.45V19h6v-2.5c0-2.33-4.67-3.5-7-3.5z"/></svg>
                                ${guests}
                            </span>
                        </div>
                    </div>
                    <div class="kd-card-body">
                        <div class="kd-badges-row">
                            <span class="kd-badge-preset">${fulfillment}</span>
                            <span class="kd-badge-timer">&#128337; ${timer}</span>
                        </div>
                        <ul class="kd-order-lines">
                            ${linesHtml}
                        </ul>
                    </div>
                    ${footerHtml}
                </div>
            `;
        }).join("");

        // Click individual food line to toggle done
        canvas.querySelectorAll(".kd-line-item").forEach(item => {
            item.onclick = async (e) => {
                e.stopPropagation();
                const lineId = item.dataset.lineId;
                const card = item.closest(".kd-order-card");
                const orderId = card ? card.dataset.orderId : null;
                if (!lineId) return;

                playSound("line_done");
                doneLines[lineId] = !doneLines[lineId];
                localStorage.setItem("hkd_done_lines", JSON.stringify(doneLines));
                renderCards();

                try {
                    await rpc("/hudson_kitchen_display/toggle_line", { line_id: lineId });
                } catch (err) {}

                const order = orders.find(o => String(o.id) === String(orderId));
                if (order && order.lines) {
                    const allDone = order.lines.every(line => isLineDone(line.id, line.is_done));
                    if (allDone) {
                        const currentIdx = stages.findIndex(s => s.id === order.stage_id);
                        if (currentIdx !== -1 && currentIdx + 1 < stages.length) {
                            const nextStage = stages[currentIdx + 1];
                            if (nextStage.name.toLowerCase().includes("complete")) {
                                playSound("completed");
                                syncOrderToTracking("ready", order, order.id);
                            } else {
                                playSound("ready");
                                syncOrderToTracking("ready", order, order.id);
                            }
                            order.lines.forEach(line => delete doneLines[line.id]);
                            localStorage.setItem("hkd_done_lines", JSON.stringify(doneLines));
                            lastMovedAction = {
                                orderId: order.id,
                                fromStageId: order.stage_id,
                                toStageId: nextStage.id,
                                timestamp: Date.now()
                            };
                            await rpc("/hudson_kitchen_display/change_stage", {
                                order_id: order.id,
                                stage_id: nextStage.id
                            });
                        }
                    }
                }
                await loadData();
            };
        });

        function syncOrderToTracking(action, order, orderId) {
            try {
                const targetId = orderId || (order ? order.id : null);
                const num = order ? (order.table_number || (order.pos_reference ? order.pos_reference.split(" ").slice(-1)[0] : "") || String(order.id)).replace(/^T/, "") : "";
                const payload = {
                    action: action,
                    id: targetId,
                    reference: num,
                    timestamp: Date.now()
                };

                let readyList = JSON.parse(localStorage.getItem("kd_tracking_ready_orders") || "[]");
                let prepList = JSON.parse(localStorage.getItem("kd_tracking_prep_orders") || "[]");

                const cutoff = Date.now() - 25 * 60 * 1000;
                readyList = readyList.filter(item => (item.timestamp || 0) >= cutoff && String(item.id) !== String(targetId));
                prepList = prepList.filter(item => (item.timestamp || 0) >= cutoff && String(item.id) !== String(targetId));

                if (action === "ready") {
                    if (num) readyList.unshift({ id: targetId, reference: num, timestamp: Date.now() });
                } else if (action === "preparing") {
                    if (num) prepList.unshift({ id: targetId, reference: num, timestamp: Date.now() });
                }

                localStorage.setItem("kd_tracking_ready_orders", JSON.stringify(readyList));
                localStorage.setItem("kd_tracking_prep_orders", JSON.stringify(prepList));

                if (window.BroadcastChannel) {
                    const bc = new BroadcastChannel("kd_order_tracking_channel");
                    bc.postMessage(payload);
                    bc.close();
                }
            } catch(e) {}
        }

        // Click Reset button
        canvas.querySelectorAll(".btn-reset").forEach(btn => {
            btn.onclick = async (e) => {
                e.stopPropagation();
                playSound("reset");
                const orderId = btn.dataset.orderId;
                const order = orders.find(o => String(o.id) === String(orderId));
                syncOrderToTracking("preparing", order, orderId);
                btn.disabled = true;
                await rpc("/hudson_kitchen_display/previous_stage", { order_id: orderId });
                await loadData();
            };
        });

        // Click Done button (Completed Stage)
        canvas.querySelectorAll(".btn-done").forEach(btn => {
            btn.onclick = async (e) => {
                e.stopPropagation();
                playSound("done");
                const orderId = btn.dataset.orderId;
                const order = orders.find(o => String(o.id) === String(orderId));
                lastMovedAction = {
                    orderId: orderId,
                    fromStageId: order ? order.stage_id : null,
                    wasMarkDone: true,
                    timestamp: Date.now()
                };

                // Push this order immediately to "Ready" on Order Screen!
                syncOrderToTracking("ready", order, orderId);

                btn.disabled = true;
                const card = btn.closest(".kd-order-card");
                if (card) card.style.opacity = "0.3";
                await rpc("/hudson_kitchen_display/mark_done", { order_id: orderId });
                await loadData();
            };
        });

        // Click card header bar to advance entire order
        canvas.querySelectorAll(".kd-card-header-bar").forEach(header => {
            header.onclick = async (e) => {
                e.stopPropagation();
                const card = header.closest(".kd-order-card");
                if (!card) return;
                const orderId = card.dataset.orderId;
                const order = orders.find(o => String(o.id) === String(orderId));
                if (!order) return;

                const currentIdx = stages.findIndex(s => s.id === order.stage_id);
                if (currentIdx !== -1 && currentIdx + 1 < stages.length) {
                    const nextStage = stages[currentIdx + 1];
                    if (nextStage.name.toLowerCase().includes("complete")) {
                        playSound("completed");
                        syncOrderToTracking("ready", order, order.id);
                    } else {
                        playSound("ready");
                        syncOrderToTracking("ready", order, order.id);
                    }
                    card.style.opacity = "0.5";
                    if (order.lines) {
                        order.lines.forEach(line => delete doneLines[line.id]);
                        localStorage.setItem("hkd_done_lines", JSON.stringify(doneLines));
                    }
                    lastMovedAction = {
                        orderId: order.id,
                        fromStageId: order.stage_id,
                        toStageId: nextStage.id,
                        timestamp: Date.now()
                    };
                    await rpc("/hudson_kitchen_display/change_stage", {
                        order_id: order.id,
                        stage_id: nextStage.id
                    });
                    await loadData();
                }
            };
        });
    }

    async function loadData() {
        try {
            const data = await rpc("/hudson_kitchen_display/get_orders", { display_id: displayId });
            if (data) {
                stages = data.stages || [];
                const newOrders = data.orders || [];

                if (!initialLoad) {
                    newOrders.forEach(o => {
                        const prevStageId = previousOrderStages[o.id];
                        if (prevStageId === undefined) {
                            // Brand new order arrived in kitchen
                            playSound("new_order");
                        } else if (prevStageId !== o.stage_id) {
                            // Order status changed
                            const newStage = stages.find(s => s.id === o.stage_id);
                            const prevStage = stages.find(s => s.id === prevStageId);
                            const newSeq = newStage ? newStage.sequence : 0;
                            const prevSeq = prevStage ? prevStage.sequence : 0;

                            if (newStage && newStage.name.toLowerCase().includes("complete")) {
                                playSound("completed");
                            } else if (newStage && newStage.name.toLowerCase().includes("ready")) {
                                playSound("ready");
                            } else if (newSeq < prevSeq) {
                                playSound("reset");
                            } else {
                                playSound("ready");
                            }
                        }
                    });
                }
                initialLoad = false;
                previousOrderStages = {};
                newOrders.forEach(o => {
                    previousOrderStages[o.id] = o.stage_id;
                });

                orders = newOrders;
                categories = data.categories || [];
                renderTabs();
                renderCategories();
                renderCards();
            }
        } catch (e) {
            console.error("Error loading orders:", e);
        }
    }

    function exitScreen() {
        if (window.opener) {
            window.close();
        } else {
            window.location.href = "/odoo/action-976";
        }
    }

    // Event Listeners
    const btnToggleSidebar = document.getElementById("btn-toggle-sidebar");
    const sidebar = document.querySelector(".kd-sidebar");
    if (btnToggleSidebar && sidebar) {
        btnToggleSidebar.onclick = () => {
            sidebar.classList.toggle("collapsed");
        };
    }

    const btnClose = document.getElementById("btn-close");
    if (btnClose) btnClose.onclick = exitScreen;

    // Sound Toggle Button
    const btnSound = document.getElementById("btn-sound-toggle");
    const soundIcon = document.getElementById("sound-icon");
    const soundText = document.getElementById("sound-text");

    function updateSoundButton() {
        if (soundIcon) soundIcon.textContent = soundEnabled ? "🔊" : "🔇";
        if (soundText) soundText.textContent = soundEnabled ? "Sound" : "Muted";
        if (btnSound) {
            btnSound.style.opacity = soundEnabled ? "1" : "0.55";
            btnSound.title = soundEnabled ? "Click to Mute Sound" : "Click to Enable Sound";
        }
    }
    updateSoundButton();

    if (btnSound) {
        btnSound.onclick = () => {
            soundEnabled = !soundEnabled;
            localStorage.setItem("hkd_sound_enabled", soundEnabled ? "1" : "0");
            updateSoundButton();
            if (soundEnabled) {
                getAudioContext();
                playSound("ready");
            }
        };
    }

    // Unlock Web Audio API on first interaction
    window.addEventListener("click", () => {
        getAudioContext();
    }, { once: true });

    const btnOpenOrderScreen = document.getElementById("btn-open-order-screen");
    if (btnOpenOrderScreen) {
        btnOpenOrderScreen.onclick = () => {
            const token = root ? root.dataset.accessToken : "";
            const url = token ? `/pos-order-tracking/?access_token=${token}` : `/hudson_kitchen_display/order_status?display_id=${displayId}`;
            window.open(url, "_blank");
        };
    }

    const btnClearDone = document.getElementById("btn-clear-done");
    if (btnClearDone) {
        btnClearDone.onclick = async () => {
            playSound("done");
            if (stages.length) {
                const lastStage = stages[stages.length - 1];
                const completedOrders = orders.filter(o => o.stage_id === lastStage.id);
                if (completedOrders.length) {
                    const lastOrder = completedOrders.sort((a, b) => new Date(b.create_date) - new Date(a.create_date))[0];
                    lastMovedAction = {
                        orderId: lastOrder.id,
                        fromStageId: lastStage.id,
                        wasMarkDone: true,
                        timestamp: Date.now()
                    };
                }
            }
            await rpc("/hudson_kitchen_display/clear_completed", { display_id: displayId });
            await loadData();
        };
    }

    const btnRecall = document.getElementById("btn-recall");
    if (btnRecall) {
        btnRecall.onclick = async () => {
            btnRecall.disabled = true;
            playSound("reset");
            try {
                if (lastMovedAction && (Date.now() - lastMovedAction.timestamp < 300000)) {
                    if (lastMovedAction.wasMarkDone) {
                        await rpc("/hudson_kitchen_display/recall", {
                            order_id: lastMovedAction.orderId,
                            display_id: displayId
                        });
                    } else {
                        await rpc("/hudson_kitchen_display/change_stage", {
                            order_id: lastMovedAction.orderId,
                            stage_id: lastMovedAction.fromStageId
                        });
                    }
                    lastMovedAction = null;
                } else {
                    // Server-side recall of the most recently modified or completed order
                    await rpc("/hudson_kitchen_display/recall", { display_id: displayId });
                }
                await loadData();
            } catch (err) {
                console.error("Recall error:", err);
            } finally {
                btnRecall.disabled = false;
            }
        };
    }

    // Touch / click tooltip toggle support for mobile & tablet screens
    document.querySelectorAll(".kd-has-tooltip .kd-help-icon").forEach(icon => {
        icon.addEventListener("click", (e) => {
            e.stopPropagation();
            const parent = icon.closest(".kd-has-tooltip");
            if (parent) {
                parent.classList.toggle("touch-tooltip-active");
                setTimeout(() => parent.classList.remove("touch-tooltip-active"), 4000);
            }
        });
    });

    const btnClearAll = document.getElementById("btn-clear-all");
    if (btnClearAll) {
        btnClearAll.onclick = async () => {
            if (confirm("Are you sure you want to reset/clear all orders?")) {
                await rpc("/hudson_kitchen_display/reset_all", { display_id: displayId });
                await loadData();
            }
        };
    }

    const btnZoomIn = document.getElementById("btn-zoom-in");
    if (btnZoomIn) {
        btnZoomIn.onclick = () => {
            zoomScale = Math.min(zoomScale + 0.1, 1.4);
            const canvas = document.getElementById("kd-canvas");
            if (canvas) canvas.style.transform = `scale(${zoomScale})`;
            if (canvas) canvas.style.transformOrigin = "top left";
        };
    }

    const btnZoomOut = document.getElementById("btn-zoom-out");
    if (btnZoomOut) {
        btnZoomOut.onclick = () => {
            zoomScale = Math.max(zoomScale - 0.1, 0.8);
            const canvas = document.getElementById("kd-canvas");
            if (canvas) canvas.style.transform = `scale(${zoomScale})`;
            if (canvas) canvas.style.transformOrigin = "top left";
        };
    }

    // Sidebar Time Filters
    document.querySelectorAll(".kd-side-row[data-time]").forEach(row => {
        row.onclick = () => {
            document.querySelectorAll(".kd-side-row[data-time]").forEach(r => r.classList.remove("active"));
            row.classList.add("active");
            currentTimeFilter = row.dataset.time;
            renderCards();
        };
    });

    // Sidebar Preset Filters
    document.querySelectorAll(".kd-side-row[data-preset]").forEach(row => {
        row.onclick = () => {
            document.querySelectorAll(".kd-side-row[data-preset]").forEach(r => r.classList.remove("active"));
            row.classList.add("active");
            currentPresetFilter = row.dataset.preset;
            renderCards();
        };
    });

    // Initial Load & Polling every 3 seconds
    loadData();
    setInterval(loadData, 3000);
})();

(function() {
    "use strict";
    const root = document.getElementById("pos_tracking_root");
    if (!root) return;
    const displayId = root.dataset.displayId;
    const accessToken = root.dataset.accessToken;

    let prevReadyIds = new Set();
    let audioCtx = null;

    function getAudioContext() {
        if (!audioCtx) {
            const AudioContext = window.AudioContext || window.webkitAudioContext;
            if (AudioContext) audioCtx = new AudioContext();
        }
        if (audioCtx && audioCtx.state === "suspended") audioCtx.resume();
        return audioCtx;
    }

    // Play double bell chime when an order enters Ready
    function playReadyBell() {
        try {
            const ctx = getAudioContext();
            if (!ctx) return;
            const now = ctx.currentTime;
            [1567.98, 2351.97].forEach((f, idx) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "triangle";
                osc.frequency.setValueAtTime(f, now);
                gain.gain.setValueAtTime(0.25, now);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.22);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(now);
                osc.stop(now + 0.22);
            });
            [1760.00, 2640.00].forEach((f, idx) => {
                const t = now + 0.14;
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = "sine";
                osc.frequency.setValueAtTime(f, t);
                gain.gain.setValueAtTime(0.30, t);
                gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.65);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start(t);
                osc.stop(t + 0.65);
            });
        } catch (e) {}
    }

    window.addEventListener("click", () => { getAudioContext(); }, { once: true });

    function renderCard(order, isReady) {
        const ref = String(order.reference || "");
        let sizeClass = "";
        if (ref.length >= 6) {
            sizeClass = "very-long";
        } else if (ref.length >= 4) {
            sizeClass = "long-number";
        }
        const bgClass = isReady ? "pos-card-ready" : "pos-card-almost";
        return `
            <div class="pos-tracking-card ${bgClass}" data-order-id="${order.id}">
                <span class="pos-card-number ${sizeClass}">${ref}</span>
            </div>
        `;
    }

    function getSharedOrders(key) {
        try {
            const cutoff = Date.now() - 25 * 60 * 1000;
            let list = JSON.parse(localStorage.getItem(key) || "[]");
            return list.filter(item => (item.timestamp || 0) >= cutoff);
        } catch(e) { return []; }
    }

    if (window.BroadcastChannel) {
        try {
            const bc = new BroadcastChannel("kd_order_tracking_channel");
            bc.onmessage = (event) => {
                if (event.data && event.data.action === "ready") {
                    playReadyBell();
                }
                update();
            };
        } catch(e) {}
    }

    async function update() {
        let readyOrders = [];
        let prepOrders = [];
        try {
            const res = await fetch("/hudson_kitchen_display/get_display_orders_status", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: { display_id: displayId, access_token: accessToken },
                    id: Date.now()
                })
            });
            const data = await res.json();
            if (data && data.result) {
                readyOrders = (data.result.ready || []).slice();
                prepOrders = (data.result.preparing || []).slice();
            }
        } catch (e) {}

        // Merge shared real-time orders (e.g. from kitchen Done button click!)
        const sharedReady = getSharedOrders("kd_tracking_ready_orders");
        const sharedPrep = getSharedOrders("kd_tracking_prep_orders");

        sharedReady.forEach(sr => {
            if (sr.reference && !readyOrders.some(ro => String(ro.reference) === String(sr.reference))) {
                readyOrders.unshift({ id: sr.id, reference: sr.reference });
            }
            prepOrders = prepOrders.filter(po => String(po.reference) !== String(sr.reference));
        });

        sharedPrep.forEach(sp => {
            if (sp.reference && !prepOrders.some(po => String(po.reference) === String(sp.reference)) && !readyOrders.some(ro => String(ro.reference) === String(sp.reference))) {
                prepOrders.unshift({ id: sp.id, reference: sp.reference });
            }
        });

        // Check if any order moved to Ready
        if (prevReadyIds.size > 0) {
            const newlyReady = readyOrders.some(o => !prevReadyIds.has(o.reference));
            if (newlyReady) playReadyBell();
        }
        prevReadyIds = new Set(readyOrders.map(o => o.reference));

        const readyEl = document.getElementById("tracking-ready-grid");
        const prepEl = document.getElementById("tracking-prep-grid");

        if (readyEl) {
            readyEl.innerHTML = readyOrders.length
                ? readyOrders.map(o => renderCard(o, true)).join("")
                : `<div class="pos-empty-hint">-</div>`;
        }

        if (prepEl) {
            prepEl.innerHTML = prepOrders.length
                ? prepOrders.map(o => renderCard(o, false)).join("")
                : `<div class="pos-empty-hint">-</div>`;
        }
    }

    update();
    setInterval(update, 2000);
})();
